193	+/// What the core does with a stream that has one quirk (allow-all, `on_failure = block`).
194	+#[derive(Debug, PartialEq, Eq)]
195	+enum Reach {
196	+    /// A malformed record or a § 6.4 deviation: the record is dropped as `malformed`.
197	+    Malformed,
198	+    /// R15: `on_failure` with code `truncated`, and no malformed record.
199	+    Truncated,
200	+    /// An upstream error record: no failure metric; the core aborts with D13 inside the hold.
201	+    Upstream,
202	+    /// R3: the record after the terminal event is dropped and counted, nothing else.
203	+    AfterEnd,
204	+    /// No failure at all.
205	+    Clean,
206	+}
207	+
208	+fn reach(q: RQuirk, at: usize) -> Reach {
209	+    use RQuirk::*;
210	+    match q {
211	+        TopLevelError | ErrorEventMidItem => Reach::Upstream,
212	+        RecordAfterTerminal => Reach::AfterEnd,
213	+        Bom | NoFinalBlankLine | KeepaliveWithoutSequence => Reach::Clean,
214	+        AbsentStatus if at % 2 == 1 => Reach::Clean,
215	+        FailedWithOpenItem if at.is_multiple_of(2) => Reach::Truncated,
216	+        DoneIncomplete | NoTerminal | AbsentStatus | EofInItem => Reach::Truncated,
217	+        _ => Reach::Malformed,
218	+    }
219	+}
220	+
221	+fn reached(o: &Outcome) -> Reach {
222	+    let has = |m: Metric| o.metrics.contains(&m);
223	+    if has(Metric::RecordDropped("malformed")) {
224	+        Reach::Malformed
225	+    } else if has(Metric::OnFailure("truncated")) {
226	+        Reach::Truncated
227	+    } else if has(Metric::RecordDropped("after_done")) && !o.metrics.iter().any(|m| matches!(m, Metric::OnFailure(_))) {
228	+        Reach::AfterEnd
229	+    } else if !o.core_failed() && (o.aborted || show(&o.out).contains("\"boom\"")) {
230	+        Reach::Upstream
231	+    } else if !o.core_failed() && !o.aborted {
232	+        Reach::Clean
233	+    } else {
234	+        panic!("an unexpected outcome: {:?}", o.metrics)
235	+    }
236	+}
