267	+                    // (It raises earlier at an apply_patch diff event, § 6.3.)
268	+                    RQuirk::TerminalItemNeverStreamed if at % 2 == 1 && !s.items.iter().any(|i| i.kind == RKind::ApplyPatch) => {
