+                segs[t].post.push(Rec::Ev(added_ev(t, hidden_call("fc_hidden"))));
+            }
+            RQuirk::IndexGap if n > 0 => {
+                let t = at % n;
+                segs[t].post.push(Rec::Ev(added_ev(t + 2, hidden_call("fc_hidden"))));
+            }
+            RQuirk::ItemNull if n > 0 => {
+                let t = at % n;
