211	+        TopLevelError | ErrorEventMidItem => Reach::Upstream,
212	+        RecordAfterTerminal => Reach::AfterEnd,
213	+        Bom | NoFinalBlankLine | KeepaliveWithoutSequence => Reach::Clean,
214	+        AbsentStatus if at % 2 == 1 => Reach::Clean,
215	+        FailedWithOpenItem if at.is_multiple_of(2) => Reach::Truncated,
216	+        DoneIncomplete | NoTerminal | AbsentStatus | EofInItem => Reach::Truncated,
